def classify(n: int) -> str:
    if n > 0:
        return "positive"
    if n < 0:
        return "negative"
    return "zero"

def withdraw(balance: int, amount: int) -> int:
    if amount <= 0:
        raise ValueError("amount")
    if amount > balance:
        raise ValueError("insufficient")
    return balance - amount
